/* ===================== BÀI 45 · Thiết kế trainer 8086 tối giản ===================== */
/* Bài 45 · Thiết kế trainer 8086 tối giản (AMTS-EMB-002-M12-L01, X86-045) — sinh bởi tools/author/mpu8086/l45.py, không sửa tay.
   Ví dụ cho trainer 8086 ảo (makeX86Trainer) và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P45=[{"label": "Ví dụ: khởi động từ FFFF0h, bật LED", "code": "; Ví dụ 1: CPU bắt đầu ở FFFF0h, nhảy về đầu ROM, bật LED\nPA      EQU     80H                     ; 8255A cổng A → 8 LED\nCW55    EQU     86H                     ; 8255A thanh ghi điều khiển\nROM     SEGMENT                         ; EPROM FC000h–FFFFFh, CS = FC00h\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H                 ; 8255A: PA ra, PB vào (mode 0)\n        OUT     CW55, AL\n        MOV     AL, 0A5H                ; 1010 0101b: LED 7, 5, 2, 0 sáng\n        OUT     PA, AL\n        HLT                             ; không có DOS: dừng ở đây\n        ORG     3FF0H                   ; FC00:3FF0 = FFFF0h, nơi CPU bắt đầu\n        JMP     FAR PTR start           ; mã máy EA 00 00 00 FC\nROM     ENDS\n        END     start\n", "input": "", "note": "Bấm Từng bước: lệnh đầu tiên chạy ở FFFF:0000 = FFFF0h là JMP xa (EA 00 00 00 FC, 15 chu kỳ) tới FC00:0000. Sau đó 82h vào 86h đặt PA là cổng ra, A5h ra PA: LED 7, 5, 2, 0 sáng. HLT kết thúc vì không có nguồn ngắt. Xem phần Bo mạch và Nhật ký bus. Đoán trước: sau JMP xa, CS và IP bằng bao nhiêu? Đáp án CS = FC00h, IP = 0000h."}, {"label": "Ví dụ: SS:SP, DS và biến trong RAM", "code": "; Ví dụ 2: khởi tạo SS:SP, DS rồi dùng biến trong RAM\nPA      EQU     80H                     ; 8 LED\nPB      EQU     82H                     ; 8 công tắc\nCW55    EQU     86H\nRAM     SEGMENT                         ; RAM từ 00400h, DS = 0040h\ncongtac DB      ?                       ; bản sao công tắc\ndem     DB      ?                       ; số bit 1 của công tắc\nRAM     ENDS\nROM     SEGMENT\n        ASSUME  CS:ROM, DS:RAM\nstart:\n        CLI                             ; chưa có vectơ ngắt nào\n        XOR     AX, AX\n        MOV     SS, AX                  ; ngăn xếp: 0000:4000h trở xuống\n        MOV     SP, 4000H\n        MOV     AX, RAM                 ; = 0040h khi nạp vào trainer\n        MOV     DS, AX\n        MOV     AL, 82H\n        OUT     CW55, AL\n        IN      AL, PB                  ; đọc 8 công tắc\n        MOV     congtac, AL\n        CALL    demBit                  ; CL = số bit 1 của AL\n        MOV     dem, CL\n        MOV     AL, CL\n        OUT     PA, AL                  ; hiện số bit 1 ra LED\n        HLT\ndemBit  PROC    NEAR                    ; vào: AL · ra: CL\n        XOR     CL, CL\n        MOV     CH, 8\nlap:\n        SHR     AL, 1                   ; bit thấp nhất vào CF\n        ADC     CL, 0                   ; CL = CL + CF\n        DEC     CH\n        JNZ     lap\n        RET\ndemBit  ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Mẫu khởi động đầy đủ: CLI, SS = 0000h, SP = 4000h (đỉnh RAM), DS = 0040h (đoạn RAM), từ điều khiển 8255A. Công tắc đặt sẵn B5h = 1011 0101b; thủ tục demBit đếm 5 bit 1 bằng SHR và ADC. CALL cất IP trả về vào 0000:3FFE (trong RAM). Đoán trước: sau CALL demBit, SP bằng bao nhiêu? Đáp án 3FFEh.", "sw": 181}, {"label": "Lỗi: gọi thủ tục khi chưa có SS:SP", "code": "; Ví dụ 3 (LỖI): gọi thủ tục khi chưa khởi tạo SS:SP\nPA      EQU     80H\nCW55    EQU     86H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        MOV     AL, 82H\n        OUT     CW55, AL\n        MOV     AL, 3\n        CALL    nhanDoi                 ; cất IP trả về ở SS:SP-2 = ?\n        OUT     PA, AL                  ; mong đợi LED = 06h\n        HLT\nnhanDoi PROC    NEAR\n        SHL     AL, 1\n        RET                             ; lấy IP trả về từ ngăn xếp\nnhanDoi ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Lỗi cố ý: không đặt SS:SP. RESET đặt SS = 0000h nhưng không xác định SP (datasheet không nêu SP trong trạng thái sau RESET); trainer ảo cho SP = 0000h (giả định của mô phỏng), nên CALL cất IP vào 0000:FFFE = 0FFFEh, nơi không có chip: byte mất. RET đọc FFFFh từ bus làm IP, CPU nạp lệnh ở FC00:FFFF = 0BFFFh (cũng không có chip) và trainer dừng với lời chẩn đoán. Sửa: thêm XOR AX, AX / MOV SS, AX / MOV SP, 4000h như Ví dụ 2. Đoán trước: CALL ghi IP trả về vào địa chỉ vật lý nào? Đáp án 0FFFEh."}, {"label": "Lỗi: biến đặt trong ROM không ghi được", "code": "; Ví dụ 4 (LỖI): khai báo biến trong đoạn ROM\nPA      EQU     80H\nCW55    EQU     86H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H\n        OUT     CW55, AL\n        MOV     dem, 0                  ; ghi vào EPROM: không có tác dụng\n        INC     dem\n        INC     dem\n        MOV     AL, dem                 ; đọc lại: vẫn là byte gốc 07h\n        OUT     PA, AL                  ; mong đợi LED = 02h\n        HLT\ndem     DB      7                       ; nằm trong EPROM (FC00:00xx)\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Lỗi cố ý: biến dem khai báo trong đoạn ROM. MOV dem, 0 và hai lệnh INC ghi vào EPROM nên không có tác dụng (trainer ghi chẩn đoán); đọc lại vẫn là 07h nên LED = 07h thay vì 02h. Sửa: khai báo dem DB ? trong RAM SEGMENT và nạp DS = RAM. Đoán trước: LED cuối cùng bằng bao nhiêu? Đáp án 07h."}, {"label": "Bẫy: cổng lẻ 81h và OUT 16 bit", "code": "; Ví dụ 5 (BẪY): cổng lẻ 81h và OUT 16 bit tới chip 8 bit\nCW55    EQU     86H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H\n        OUT     CW55, AL\n        MOV     AL, 0FFH\n        OUT     81H, AL                 ; 81h = 1000 0001b: A0 = 1\n        MOV     AX, 0F00FH              ; ghi word: AL → cổng 80h, AH → 81h\n        OUT     80H, AX\n        HLT\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Bẫy: OUT 81h, AL ghi ra cổng lẻ, byte đi trên D8–D15 nơi không có chip nên mất (Nhật ký bus: cổng lẻ). OUT 80h, AX ghi 2 byte: AL = 0Fh tới PA, AH = F0h tới 81h (mất). LED = 0Fh chứ không phải FFh hay F00Fh. Đoán trước: sau OUT 81h, AL, LED đổi không? Đáp án không, vẫn tắt hết (00h)."}, {"label": "Ví dụ: kiểm 1 KB RAM bằng lệnh chuỗi", "code": "; Ví dụ 6: kiểm 1 KB RAM (00400h–007FFh) bằng lệnh chuỗi\nPA      EQU     80H\nCW55    EQU     86H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H\n        OUT     CW55, AL\n        MOV     AX, 0040H               ; ES:DI = 0040:0000 = 00400h\n        MOV     ES, AX\n        CLD                             ; DI tăng sau mỗi word\n        XOR     DI, DI\n        MOV     CX, 512                 ; 512 word = 1 KB\n        MOV     AX, 55AAH               ; mẫu 0101 0101 1010 1010b\n        REP     STOSW                   ; ghi mẫu vào cả vùng\n        XOR     DI, DI\n        MOV     CX, 512\n        REPE    SCASW                   ; so từng word với AX\n        MOV     AL, 0                   ; 00h = RAM tốt\n        JE      tot                     ; ZF = 1: mọi word bằng mẫu\n        MOV     AL, 0FFH                ; FFh = có ô hỏng\ntot:\n        OUT     PA, AL\n        HLT\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Kiểm 1 KB RAM: REP STOSW ghi 512 word 55AAh (9 + 10 × 512 = 5129 chu kỳ), REPE SCASW so lại (9 + 15 × 512 = 7689 chu kỳ). ZF = 1 sau khi so hết nghĩa là mọi word bằng mẫu. Xem Bộ nhớ ở 00400h: AA 55 (byte thấp trước). Đoán trước: REP STOSW tốn bao nhiêu chu kỳ? Đáp án 5129."}, {"label": "Ví dụ: kế hoạch ngắt 100 Hz qua 8259A", "code": "; Ví dụ 7: kế hoạch ngắt: 8254 100 Hz → IR0 → vectơ 40h\nPA      EQU     80H\nRAM     SEGMENT\ntick    DB      ?                       ; số ngắt timer đã nhận\nRAM     ENDS\nROM     SEGMENT\n        ASSUME  CS:ROM, DS:RAM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     DS, AX                  ; DS = 0 để ghi bảng vectơ\n        MOV     WORD PTR DS:[40H*4], OFFSET isr0\n        MOV     WORD PTR DS:[40H*4+2], ROM\n        MOV     AX, RAM\n        MOV     DS, AX\n        MOV     tick, 0\n        MOV     AL, 82H                 ; 8255A: PA ra\n        OUT     86H, AL\n        MOV     AL, 13H                 ; ICW1: kích cạnh, 1 chip, có ICW4\n        OUT     90H, AL\n        MOV     AL, 40H                 ; ICW2: IR0 → vectơ 40h\n        OUT     92H, AL\n        MOV     AL, 01H                 ; ICW4: chế độ 8086, EOI thường\n        OUT     92H, AL\n        MOV     AL, 0FEH                ; OCW1: chỉ mở IR0\n        OUT     92H, AL\n        MOV     AL, 34H                 ; 8254 bộ đếm 0, LSB rồi MSB, mode 2\n        OUT     8EH, AL\n        MOV     AX, 25000               ; 2,5 MHz / 25000 = 100 Hz\n        OUT     88H, AL\n        MOV     AL, AH\n        OUT     88H, AL\n        STI\ncho:\n        HLT                             ; chờ ngắt\n        CMP     tick, 3\n        JB      cho\n        CLI\n        HLT                             ; đủ 3 ngắt: dừng hẳn\nisr0:\n        PUSH    AX                      ; ISR không được làm hỏng AX\n        INC     tick\n        MOV     AL, tick\n        OUT     PA, AL                  ; LED = số ngắt\n        MOV     AL, 20H                 ; EOI thường cho 8259A\n        OUT     90H, AL\n        POP     AX\n        IRET\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "input": "", "note": "Kế hoạch ngắt chạy thật: ghi vectơ 40h vào 00100h (OFFSET isr0, đoạn ROM), khởi tạo 8259A (13h, 40h, 01h, FEh), 8254 mode 2 với N = 25 000 → ngắt mỗi 10 ms. CPU chờ ở HLT; mỗi ngắt ISR tăng tick, đưa ra LED và gửi EOI. Sau 3 ngắt: LED = 03h. Phần Bo mạch cho thời gian CPU và thời gian chờ HLT. Đoán trước: vectơ 40h nằm ở địa chỉ vật lý nào? Đáp án 00100h (40h × 4)."}];
const sim45=makeX86Trainer(document.getElementById("x86-l45"),{id:"s45",presets:P45,file:"ROM45.ASM"});
makeX86TrainerEx(document.getElementById("ex-l45"),sim45,[{"t": "LED là công tắc đảo bit", "d": "Trên trainer AMTS-86: ghi từ điều khiển 82h cho 8255A (PA ra, PB vào, mode 0), đọc 8 công tắc ở PB (82h), đảo cả 8 bit rồi đưa ra 8 LED ở PA (80h): công tắc gạt lên (1) thì LED tương ứng tắt. Dừng bằng HLT. Giữ ORG 3FF0h và lệnh JMP xa ở cuối đoạn ROM.", "start": "; Bài tập 1: LED là công tắc đảo bit\nPA      EQU     80H                     ; 8255A cổng A → 8 LED\nPB      EQU     82H                     ; 8255A cổng B ← 8 công tắc\nCW55    EQU     86H                     ; 8255A thanh ghi điều khiển\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n; Viết code ở đây: đặt 8255A (PA ra, PB vào),\n; đọc công tắc, đảo mọi bit, đưa ra LED\n        HLT\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"sw": 0, "leds": 255, "dev": {"ppiCw": 130}}, {"sw": 255, "leds": 0, "dev": {"ppiCw": 130}}, {"sw": 15, "leds": 240, "dev": {"ppiCw": 130}}, {"sw": 165, "leds": 90, "dev": {"ppiCw": 130}}, {"sw": 129, "leds": 126, "dev": {"ppiCw": 130}}, {"sw": 60, "leds": 195, "dev": {"ppiCw": 130}}]}, {"t": "Chip nào trả lời ở địa chỉ này?", "d": "Bản đồ bộ nhớ của trainer: RAM 00000h–03FFFh, EPROM FC000h–FFFFFh, vùng khác không có chip. Terminal gửi tới 8251A hai chữ số hệ 16 viết hoa (0–9, A–F): chữ số thứ nhất là A19–A16, chữ số thứ hai là A15–A12 của một địa chỉ vật lý. In ra terminal RAM, ROM hoặc -- (hai dấu trừ) tùy chip trả lời ở địa chỉ đó, rồi dừng bằng HLT. Dùng các thủ tục nhan, gui có sẵn.", "start": "; Bài tập 2: chip nào trả lời ở địa chỉ vật lý này?\nDATA51  EQU     98H                     ; 8251A dữ liệu\nCTRL51  EQU     9AH                     ; 8251A điều khiển / trạng thái\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        CLI\n        XOR     AX, AX\n        MOV     SS, AX\n        MOV     SP, 4000H\n        MOV     AL, 4EH                 ; ×16, 8 bit, không chẵn lẻ, 1 bit stop\n        OUT     CTRL51, AL\n        MOV     AL, 37H                 ; lệnh: TxEN, DTR, RxE, ER, RTS\n        OUT     CTRL51, AL\n        CALL    nhan                    ; chữ số hệ 16 thứ nhất: A19–A16\n        MOV     BH, AL\n        CALL    nhan                    ; chữ số thứ hai: A15–A12\n        MOV     BL, AL\n; Viết code ở đây: đổi BH, BL ra giá trị 0–15,\n; in RAM, ROM hoặc -- bằng thủ tục gui\n        MOV     AL, 2DH                 ; mã ASCII của dấu trừ\n        CALL    gui\n        MOV     AL, 2DH                 ; mã ASCII của dấu trừ\n        CALL    gui\n        HLT\ngui     PROC    NEAR                    ; gửi AL ra terminal\n        PUSH    AX\ncho1:\n        IN      AL, CTRL51\n        TEST    AL, 01H                 ; TxRDY = 1?\n        JZ      cho1\n        POP     AX\n        OUT     DATA51, AL\n        RET\ngui     ENDP\nnhan    PROC    NEAR                    ; nhận một ký tự vào AL\n        IN      AL, CTRL51\n        TEST    AL, 02H                 ; RxRDY = 1?\n        JZ      nhan\n        IN      AL, DATA51\n        RET\nnhan    ENDP\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"in": "03", "out": "RAM"}, {"in": "04", "out": "--"}, {"in": "FC", "out": "ROM"}, {"in": "FB", "out": "--"}, {"in": "00", "out": "RAM"}, {"in": "F0", "out": "--"}, {"in": "3F", "out": "--"}, {"in": "FF", "out": "ROM"}]}, {"t": "Xóa nhanh N KB RAM", "d": "Công tắc PB cho N (1–15). Ghi 0 vào N × 1024 byte RAM bắt đầu từ 00400h (không được ghi ngoài vùng này, kể cả bảng vectơ ở dưới 00400h), rồi đưa N ra LED và dừng bằng HLT. Code mẫu đúng nhưng chậm (mỗi byte một vòng lặp). Viết lại để mọi test chạy không quá 80 000 chu kỳ CPU và mã không quá 40 byte (tính cả lệnh JMP xa ở FFFF0h).", "start": "; Bài tập 3: xóa nhanh N KB RAM từ 00400h (N = công tắc)\n; Bản này đúng nhưng chậm: mỗi byte một vòng lặp.\nPA      EQU     80H\nPB      EQU     82H\nCW55    EQU     86H\nROM     SEGMENT\n        ASSUME  CS:ROM\nstart:\n        MOV     AL, 82H\n        OUT     CW55, AL\n        IN      AL, PB                  ; AL = N (1–15)\n        MOV     BL, AL                  ; giữ N để báo ra LED\n        MOV     AH, 0\n        MOV     CL, 10\n        SHL     AX, CL                  ; AX = N × 1024 byte\n        MOV     CX, AX\n        MOV     AX, 0040H               ; ES:DI = 0040:0000 = 00400h\n        MOV     ES, AX\n        MOV     DI, 0\nxoa:\n        MOV     BYTE PTR ES:[DI], 0\n        INC     DI\n        LOOP    xoa\n        MOV     AL, BL\n        OUT     PA, AL                  ; báo xong: LED = N\n        HLT\n        ORG     3FF0H\n        JMP     FAR PTR start\nROM     ENDS\n        END     start\n", "tests": [{"sw": 1, "leds": 1, "phys": [{"at": 1024, "bytes": [0, 0, 0, 0]}, {"at": 1536, "bytes": [0, 0]}, {"at": 2044, "bytes": [0, 0, 0, 0]}], "keep": [1022, 1023, 2048, 2049]}, {"sw": 2, "leds": 2, "phys": [{"at": 1024, "bytes": [0, 0, 0, 0]}, {"at": 2048, "bytes": [0, 0]}, {"at": 3068, "bytes": [0, 0, 0, 0]}], "keep": [1022, 1023, 3072, 3073]}, {"sw": 7, "leds": 7, "phys": [{"at": 1024, "bytes": [0, 0, 0, 0]}, {"at": 4608, "bytes": [0, 0]}, {"at": 8188, "bytes": [0, 0, 0, 0]}], "keep": [1022, 1023, 8192, 8193]}, {"sw": 14, "leds": 14, "phys": [{"at": 1024, "bytes": [0, 0, 0, 0]}, {"at": 8192, "bytes": [0, 0]}, {"at": 15356, "bytes": [0, 0, 0, 0]}], "keep": [1022, 1023, 15360, 15361]}, {"sw": 15, "leds": 15, "phys": [{"at": 1024, "bytes": [0, 0, 0, 0]}, {"at": 8704, "bytes": [0, 0]}, {"at": 16380, "bytes": [0, 0, 0, 0]}], "keep": [1022, 1023]}], "perf": {"cycles": 80000, "bytes": 40}}]);

makeQuiz("quiz45","score45",[{"q": "Trainer có EPROM 16 KB phủ FFFF0h. Vì sao lệnh ở FFFF0h phải là một lệnh nhảy xa chứ không viết chương trình ngay tại đó?", "o": ["Lệnh ở FFFF0h luôn chạy với IF = 1 nên dễ bị ngắt", "8086 chỉ đọc được 5 byte đầu tiên sau RESET", "EPROM chỉ cho chạy lệnh nhảy ở địa chỉ chẵn", "Từ FFFF0h tới hết bộ nhớ chỉ còn 16 byte"], "a": 3, "e": "FFFF0h + 16 = 100000h vượt 1 MB, nên chỉ có 16 byte (FFFF0h–FFFFFh). Lệnh JMP FAR PTR start (5 byte, EA 00 00 00 FC) nhảy về đầu EPROM ở FC000h. Sau RESET thanh ghi cờ bị xóa nên IF = 0."}, {"q": "Với giải mã đầy đủ A19–A14 như trainer, đoạn code sau ghi byte 55h vào đâu?<pre class=\"mp-asm\">        MOV     AX, 0400H\n        MOV     ES, AX\n        MOV     BYTE PTR ES:[0], 55H<\/pre>", "o": ["Ô RAM 00400h, đầu đoạn RAM của chương trình", "Ô RAM 00000h vì RAM chỉ có 16 KB nên quay vòng", "Địa chỉ 04000h: không chip nào, byte bị mất", "Ô EPROM FC000h vì đó là vùng nhớ gần nhất"], "a": 2, "e": "ES × 16 + 0 = 04000h; A19–A14 = 0000 01 không khớp RAM (0000 00) cũng không khớp EPROM (1111 11). Giải mã đầy đủ nên không có địa chỉ ảnh: byte mất, trainer ghi chẩn đoán. Nhầm 0040h (đoạn) với 0400h là lỗi hay gặp."}, {"q": "8255A của trainer nối D0–D7, giải mã ở 80h–86h. Đoạn sau làm LED (PA) hiện gì?<pre class=\"mp-asm\">        MOV     AL, 82H\n        OUT     86H, AL\n        MOV     AX, 3CC3H\n        OUT     80H, AX<\/pre>", "o": ["3Ch: byte cao của AX tới PA trước", "C3h: AL tới PA, AH tới cổng lẻ 81h bị mất", "3CC3h: PA nhận đủ 16 bit của AX", "Không đổi: OUT 16 bit bị 8255A bỏ qua"], "a": 1, "e": "OUT word tới cổng chẵn 80h: AL lên D0–D7 tới cổng 80h, AH lên D8–D15 tới cổng 81h. Không chip nào ở 81h nên AH mất; PA = C3h (Ví dụ 5)."}, {"q": "Kế hoạch ngắt dùng ICW2 = 40h, IR1 nối nút NGẮT. Chương trình phải ghi địa chỉ ISR của nút vào ô nhớ nào?", "o": ["00100h–00103h (vectơ 40h × 4)", "00041h–00044h (số vectơ 41h)", "00104h–00107h (vectơ 41h × 4)", "92h, cổng ICW2 của 8259A"], "a": 2, "e": "IR1 → vectơ 40h + 1 = 41h; mỗi vectơ 4 byte (IP rồi CS) ở 41h × 4 = 104h. Vectơ 40h (00100h) là của IR0 (timer)."}, {"q": "Kế hoạch kiểm thử nào xếp đúng thứ tự từ khối ít phụ thuộc nhất?", "o": ["Ngắt timer → RAM, ngăn xếp → 8255A → nạp lệnh từ EPROM", "8251A gửi chữ → ngắt timer → RAM → nạp lệnh từ EPROM", "RAM, ngăn xếp → ngắt timer → nạp lệnh từ EPROM → 8255A", "Nạp lệnh từ EPROM → RAM, ngăn xếp → 8255A → ngắt timer"], "a": 3, "e": "Mọi phép thử đều cần CPU nạp được lệnh từ EPROM, nên thử trước. Ngắt timer cần RAM (vectơ, ngăn xếp), 8259A, 8254 nên thử sau cùng; khi nó hỏng, các khối bên dưới đã được loại trừ."}]);

